import React, { useEffect, useState } from 'react';
import { View, Text, FlatList, TouchableOpacity, Button, StyleSheet } from 'react-native';
import axios from 'axios';

export default function ListScreen({ navigation, route }) {
  const [sensors, setSensors] = useState([]);
  const [apiUrl, setApiUrl] = useState(route.params?.apiUrl || 'http://localhost:3000');

  const fetchData = async () => {
    try {
      const response = await axios.get(`${apiUrl}/sensors`);
      setSensors(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchData();
  }, [apiUrl]);

  return (
    <View style={styles.container}>
      <Button title="Configurar" onPress={() => navigation.navigate('Config', { apiUrl, setApiUrl })} />
      <FlatList
        data={sensors}
        keyExtractor={(item) => item.id.toString()}
        renderItem={({ item }) => (
          <TouchableOpacity onPress={() => navigation.navigate('Detail', { sensor: item, apiUrl })}>
            <View style={styles.item}>
              <Text>{item.name}</Text>
              <Text>Valor: {item.value}</Text>
              <Text>Status: {item.status}</Text>
            </View>
          </TouchableOpacity>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  item: { padding: 16, borderBottomWidth: 1 }
});
